import numpy as np,pandas as pd,joblib
D=pd.read_csv('b3_fatigue_data.csv');X=D.drop(columns='target');models=joblib.load('/tmp/fatigue_models.pkl');x=X.iloc[-1].to_numpy()
rows=[]
for ct in [469.8,480,490,500,505,510,514,520,525,530,535,540]:
 for qm in [60,80,95,100,110,120,125,130,133,140]:
  p=x.copy();p[5]=ct;p[8]=qm;rows.append(p)
A=np.array(rows);P=np.array([m.predict(pd.DataFrame(A,columns=X.columns)) for m in models.values()]);mean=P.mean(axis=0)
print(pd.DataFrame({'Ct':A[:,5],'QmT':A[:,8],'prediction':mean}).pivot(index='Ct',columns='QmT',values='prediction').round(1).to_string())
for ct,qm in [(510,125),(514,130),(525,125),(530,125),(540,125),(540,140)]:
 p=x.copy();p[5]=ct;p[8]=qm
 for interior in [False,True]:
  if interior:p[0]=885.7;p[4]=885.7;p[10]=114.2;p[1]=31.6
  pts=[p.copy()];labs=['nominal']
  for j,col in enumerate(X.columns):
   for t in np.linspace(-.05,.05,21):
    a=p.copy();a[j]*=1+t;pts.append(np.clip(a,X.min(),X.max()));labs.append((col,round(t,3)))
  P=np.array([m.predict(pd.DataFrame(pts,columns=X.columns)) for m in models.values()]);mn=P.mean(axis=0)
  print('ct',ct,'qm',qm,'interior',interior,'nominal',round(mn[0],1),'min',round(mn.min(),1),'at',labs[mn.argmin()],'worst indiv',P.min(axis=1).round(1))
